ALTER TABLE fare_product
    ADD CONSTRAINT fare_product_range_ck
    CHECK (
        validity_in_minutes >= 15
        AND validity_in_minutes <= 43200
    );

-- Application inserts and direct database writes share this constraint.
COMMIT;

